messages.content:
Tool response:
Tool: find_resources
Description: Find Resources
Parameters:
    {
      "type": "object",
      "properties": {
        "resource_type": {
          "type": "string",
          "description": "Type of resource to filter by ('station' or 'equipment')",
          "title": "Resource Type"
        }
      },
      "required": [
        "resource_type"
      ]
    }

Tool response:
Tool: create_reservation
Description: Create Reservation
Parameters:
    {
      "type": "object",
      "properties": {
        "resource_id": {
          "type": "integer",
          "title": "Resource Id"
        },
        "start_time": {
          "type": "string",
          "title": "Start Time"
        },
        "end_time": {
          "type": "string",
          "title": "End Time"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "resource_id",
        "start_time",
        "end_time"
      ]
    }
